// helmet uses `export = helmet` (CommonJS), so ContentSecurityPolicyOptions must be
// imported from its submodule directly rather than from the package root.
import type { ContentSecurityPolicyOptions } from 'helmet/dist/middlewares/content-security-policy';
import type { IncomingMessage, ServerResponse } from 'http';
import { randomBytes } from 'crypto';

// SFCC-856 — nonce-based `style-src` so Chakra UI's runtime (emotion) style
// injection no longer needs a blanket 'unsafe-inline'. helmet 4.6.0's CSP
// directive values accept a function of (req, res) => string, invoked once
// per request (helmet/dist/middlewares/content-security-policy/index.d.ts),
// which is what makes a per-request nonce possible from this file alone —
// no change to ssr.js is required, since `contentSecurityPolicy` is already
// passed through to `helmet()` there as a plain value and is re-evaluated
// per request regardless.
//
// `res` is always the real Express Response at runtime — this config is
// only ever consumed by `helmet()` inside the Express app in ssr.js — but
// helmet's own directive-function type only declares the plain Node
// `http.ServerResponse` shape (no `.locals`). Widening the function's own
// parameter type to include `.locals` would make it a narrower (subtype)
// parameter than helmet's declared function type expects, which fails
// assignability under `strictFunctionTypes` (tsconfig.json has `strict:
// true`) — so the parameter stays typed exactly as the interface declares,
// and `.locals` access goes through a single, explained assertion instead.
type ResponseWithLocals = ServerResponse & { locals: Record<string, unknown> };

const CSP_NONCE_LOCALS_KEY = 'cspNonce';

/**
 * Returns this request's CSP nonce, generating and caching it on
 * `res.locals` the first time it's requested so every directive that needs
 * it shares one value for the lifetime of the request. `res.locals` is the
 * same object `@salesforce/pwa-kit-react-sdk`'s SSR render pipeline passes
 * straight through as the `locals` prop to `AppConfig`
 * (`overrides/app/components/_app-config/index.tsx`), which reads this same
 * key back off it to configure Chakra/emotion's style-tag cache with a
 * matching nonce — again with no ssr.js involvement, since that pass-through
 * already happens inside the SDK's own render pipeline.
 */
const getOrCreateNonce = (res: ServerResponse): string => {
  const resWithLocals = res as ResponseWithLocals; // see ResponseWithLocals comment above
  const existing = resWithLocals.locals[CSP_NONCE_LOCALS_KEY];
  if (typeof existing === 'string') return existing;
  const nonce = randomBytes(16).toString('base64');
  resWithLocals.locals[CSP_NONCE_LOCALS_KEY] = nonce;
  return nonce;
};

export const contentSecurityPolicy: ContentSecurityPolicyOptions = {
  useDefaults: true,
  directives: {
    'img-src': [
      // Default source for product images - replace with your CDN
      '*.commercecloud.salesforce.com',
      '*.demandware.net',
      '*.adyen.com', // Payment gateways
      'pay.google.com', // Google Pay payment handler icon
      'www.gstatic.com', // optional, if icon is on gstatic
      // Contentful images
      'images.ctfassets.net',
    ],
    'script-src': [
      // Used by the service worker in /worker/main.js
      'storage.googleapis.com',
      // Connect to Google Cloud APIs
      'maps.googleapis.com',
      'places.googleapis.com',
      // Payment gateways
      '*.stripe.com',
      '*.paypal.com',
      '*.adyen.com',
      'pay.google.com',
      'www.gstatic.com',
      '*.demandware.net', // Used to load a valid payment scripts in test environment
      // Measmerize sizing widget (PDP)
      'client.measmerize.com',
      'static.client.measmerize.com',
    ],
    // SFCC-856 follow-up — split into `style-src-elem`/`style-src-attr` rather than one
    // combined `style-src`. CSP nonces can only ever apply to <style> ELEMENTS, never to a
    // raw inline `style="..."` ATTRIBUTE (there's no way to carry a nonce on an attribute
    // value) — but per the CSP3 spec, a nonce present anywhere in `style-src` disables
    // `'unsafe-inline'` for *everything* that directive governs, attributes included. A
    // combined `style-src` with both a nonce and 'unsafe-inline' therefore silently broke
    // every inline `style=` attribute in the app (e.g. the icon sprite sheet's
    // `style="position:absolute;width:0;height:0"` hiding technique) — confirmed live on the
    // MRT preview for this branch: a visible sprite sheet pushed a white gap above the page.
    // `style-src-elem` (the actual <style>/emotion-managed source: Chakra's runtime styling
    // plus the ZimmFontFace/ZimmTokensGlobal <Global> elements _app-config renders, all
    // sharing the nonce via the @emotion/react CacheProvider) keeps the nonce; `style-src-attr`
    // stays a plain 'unsafe-inline' with no nonce, since attributes have no nonce mechanism to
    // downgrade in the first place.
    //
    // `style-src` itself (CodeRabbit-flagged, correctly) still needs an explicit value even
    // though `style-src-elem`/`style-src-attr` cover every browser this app actually targets:
    // with `useDefaults: true` and no explicit `style-src` here, helmet 4.6.0 silently injects
    // its own default ('self' https: 'unsafe-inline') as the fallback for any browser that
    // doesn't understand the split directives, rather than us choosing that value on purpose.
    // Set explicitly below to the same conservative list this app used before nonces existed,
    // so the legacy-browser fallback is a deliberate, documented choice, not implicit helmet
    // behaviour.
    'style-src': ["'self'", "'unsafe-inline'", 'static.client.measmerize.com'],
    'style-src-elem': [
      "'self'",
      (_req: IncomingMessage, res: ServerResponse) => `'nonce-${getOrCreateNonce(res)}'`,
      "'unsafe-inline'", // CSP3 fallback for browsers predating nonce support
      // @chakra-ui/color-mode's `preventTransition()` (used by useColorMode/setDataset on
      // every color-mode change, including initial hydration) creates a raw <style> element
      // via document.createElement('style') + a static text node, entirely outside
      // React/emotion — so it can never carry our nonce. Confirmed live: this blocked with
      // "Applying inline style violates... style-src-elem" on every page load. The injected
      // content is a fixed literal baked into the package
      // (node_modules/@chakra-ui/color-mode/dist/color-mode.utils.js's `preventTransition`),
      // not request-dependent, so a CSP hash source is the correct fix rather than trying to
      // give a third-party DOM-API call our nonce. Fragile to a Chakra version bump: if this
      // exact string ever changes, recompute via
      // `node -e "console.log('sha256-' + require('crypto').createHash('sha256').update('<paste the new preventTransition() CSS string>','utf8').digest('base64'))"`.
      "'sha256-GNF74DLkXb0fH3ILHgILFjk1ozCF3SNXQ5mQb7WLu/Y='",
      // Measmerize brand-specific CSS bundle
      'static.client.measmerize.com',
    ],
    'style-src-attr': ["'unsafe-inline'"],
    'connect-src': [
      // Connect to Contentful API
      'cdn.contentful.com',
      'preview.contentful.com',
      // Connect to Einstein APIs
      'api.cquotient.com',
      // Connect to DataCloud APIs
      '*.c360a.salesforce.com',
      // Connect to Google Cloud APIs
      'maps.googleapis.com',
      'places.googleapis.com',
      // Connect to SCRT2 URLs
      '*.salesforce-scrt.com',
      // Payment gateways
      // Note: Google Pay requires different CSP entries depending on the integration and environment.
      // - 'pay.google.com' and 'payments.google.com' are generally needed for the SDK to load and create payment tokens.
      // - 'google.com/pay/' and 'www.google.com/pay/' may be required for certain flows (especially with Adyen) or in some browsers
      //   where the interactive payment sheet makes server calls directly to google.com/pay.
      // - You may need to adjust these URLs based on your environments.
      '*.demandware.net', // Used to load a valid payment scripts in test environment
      '*.adyen.com',
      '*.paypal.com',
      'pay.google.com',
      'payments.google.com',
      'google.com/pay',
      'google.com/pay/',
      'www.google.com/pay',
      'www.google.com/pay/',
      // Measmerize sizing widget (PDP)
      'client.measmerize.com',
      'api.client.measmerize.com',
    ],
    'frame-src': [
      // Allow frames from Salesforce site.com (Needed for MIAW)
      '*.site.com',
      // Payment gateways
      '*.stripe.com',
      '*.paypal.com',
      '*.adyen.com',
      'payments.google.com',
      'pay.google.com',
    ],
    // Allow Contentful to embed /preview in its Live Preview iframe
    'frame-ancestors': ["'self'", 'https://app.contentful.com'],
  },
};

